       const labels:Record<string,string>={host_list:'Inspecting a host directory.',host_read:'Reading an authorized host file.',host_write:'Writing a host file.',host_delete:'Deleting an authorized host file.',file_read:'Reading authorized files.',file_list:'Inspecting the workspace.',file_search:'Searching the workspace.',file_write:'Writing a workspace file.',file_delete:'Deleting an authorized workspace file.',terminal:'Running an isolated command.',git_status:'Inspecting workspace changes.',git_diff:'Inspecting the file diff.',http_get:'Reading an authorized web source.',mcp_call:'Calling an approved external tool.'};
